    ("Bayes' theorem", ('math', 'probability',), 'P(H|E) = P(E|H) P(H) / P(E). Posterior odds equal prior odds times the likelihood ratio.'),
    ('Central limit theorem', ('math', 'probability',), 'The sum of many independent random variables with finite variance tends toward a Gaussian.'),
    ('Law of large numbers', ('math', 'probability',), 'Sample averages converge to the expected value as n grows.'),
    ('Pythagorean theorem', ('math', 'geometry',), 'In a right triangle, a² + b² = c². The square on the hypotenuse equals the sum of the other two.'),
    ("Euler's identity", ('math', 'complex',), 'e^{iπ} + 1 = 0. It ties e, i, π, 1, and 0 in one equation.'),
    ('Fundamental theorem of calculus', ('math', 'calculus',), 'Differentiation and integration are inverses: d/dx ∫_a^x f = f(x) (under mild conditions).'),
    ('Fundamental theorem of algebra', ('math', 'algebra',), 'Every non-constant polynomial with complex coefficients has at least one complex root.'),
    ("Noether's theorem", ('physics', 'symmetry',), 'Every differentiable symmetry of the action has a corresponding conservation law.'),
    ("Maxwell's equations", ('physics', 'electromagnetism',), 'Gauss, Gauss for magnetism, Faraday, and Ampère–Maxwell: they unify electricity, magnetism, and light.'),
    ('Schrödinger equation', ('physics', 'quantum',), 'iħ ∂ψ/∂t = Ĥψ. The wavefunction evolves unitarily under the Hamiltonian.'),
    ('Heisenberg uncertainty', ('physics', 'quantum',), 'σx σp ≥ ħ/2. Position and momentum cannot both be arbitrarily sharp.'),
    ('Second law of thermodynamics', ('physics', 'thermo',), 'Entropy of an isolated system does not decrease. Heat does not spontaneously flow cold to hot.'),
    ('First law of thermodynamics', ('physics', 'thermo',), 'ΔU = Q − W. Energy is conserved; heat and work are its transfers.'),
    ("Ohm's law", ('physics', 'electricity',), 'V = IR for many materials at fixed temperature. Voltage equals current times resistance.'),
    ("Newton's laws", ('physics', 'mechanics',), 'Inertia; F = ma; action-reaction. They are the low-speed limit of relativistic mechanics.'),
    ("Hooke's law", ('physics', 'mechanics',), 'F = −kx for small springs. Restoring force proportional to displacement.'),
    ("Snell's law", ('physics', 'optics',), 'n1 sin θ1 = n2 sin θ2. Light bends at an interface of refractive indices.'),
    ('Doppler effect', ('physics', 'waves',), 'Observed frequency shifts when source or observer moves relative to the wave medium or each other.'),
    ('Photoelectric effect', ('physics', 'quantum',), 'Light ejects electrons above a frequency threshold. Einstein explained it with photons.'),
    ('Black-body radiation', ('physics', 'quantum',), "A perfect absorber emits a spectrum set by temperature. Planck's law started quantum theory."),
    ('Special relativity', ('physics', 'relativity',), 'c is invariant. Time dilates, lengths contract, E = mc², simultaneity is relative.'),
    ('General relativity', ('physics', 'relativity',), 'Mass-energy curves spacetime; free fall follows geodesics. Explains gravity as geometry.'),
    ('Standard Model', ('physics', 'particle',), 'Quarks, leptons, gauge bosons, and the Higgs. Gravity is not included.'),
    ('DNA', ('biology', 'genetics',), 'Deoxyribonucleic acid stores genes as A,T,C,G base pairs in a double helix.'),
    ('RNA', ('biology', 'genetics',), 'Ribonucleic acid: messenger, transfer, ribosomal. Often single-stranded. Uses U not T.'),
    ('Natural selection', ('biology', 'evolution',), 'Heritable variation plus differential reproduction yields adaptation over generations.'),
    ('Cell theory', ('biology', 'cell',), 'All organisms are made of cells; cells come from cells; the cell is the basic unit of life.'),
    ('Mitosis', ('biology', 'cell',), 'Somatic cell division that yields two genetically similar diploid daughters.'),
    ('Meiosis', ('biology', 'cell',), 'Reduction division that yields haploid gametes and shuffles alleles.'),
    ('Krebs cycle', ('biology', 'metabolism',), 'Citric acid cycle in mitochondria oxidizes acetyl-CoA, feeding NADH/FADH2 to the ETC.'),
    ('Glycolysis', ('biology', 'metabolism',), 'Glucose → two pyruvate, net 2 ATP and 2 NADH, in the cytosol, anaerobic-capable.'),
    ('Neuron', ('biology', 'brain',), 'Electrically excitable cell. Dendrites receive, axon transmits, synapses release transmitter.'),
    ('Action potential', ('biology', 'brain',), 'All-or-none spike from voltage-gated Na+ then K+ currents along an axon.'),
    ('Immune system', ('biology', 'health',), 'Innate barriers plus adaptive B and T cells that remember antigens.'),
    ('CRISPR', ('biology', 'genetics',), 'Bacterial adaptive immunity; Cas9 can cut DNA at a guide-RNA-specified site.'),
    ('Big O notation', ('cs', 'complexity',), 'Asymptotic upper bound on growth. O(n log n) sorts, O(1) hash lookup expected.'),
    ('Hash table', ('cs', 'data-structure',), 'Array of buckets addressed by hash(key). Average O(1) insert/lookup with a good hash.'),
    ('Binary search', ('cs', 'algorithm',), 'On a sorted array, discard half each step. O(log n) comparisons.'),
    ('Quicksort', ('cs', 'algorithm',), 'Partition around a pivot, recurse. Average O(n log n), worst O(n²) if pivots are bad.'),
    ('Mergesort', ('cs', 'algorithm',), 'Split, sort halves, merge. Guaranteed O(n log n), stable, extra memory.'),
    ("Dijkstra's algorithm", ('cs', 'graph',), 'Shortest paths from a source on non-negative weighted graphs via a priority queue.'),
    ('A* search', ('cs', 'graph',), 'Best-first search with f = g + h. Optimal if h is admissible.'),
    ('PageRank', ('cs', 'graph',), 'Stationary distribution of a random walk on the web graph, with teleportation.'),
    ('TCP', ('cs', 'network',), 'Reliable, ordered, congestion-controlled byte stream over IP. Three-way handshake.'),
    ('UDP', ('cs', 'network',), 'Unreliable datagrams over IP. Low overhead, used for DNS, games, media.'),
    ('HTTP', ('cs', 'network',), 'Application protocol: methods, headers, status codes. HTTP/2 multiplexes, HTTP/3 uses QUIC.'),
    ('TLS', ('cs', 'security',), 'Transport Layer Security: certificates, key exchange, AEAD. HTTPS is HTTP over TLS.'),
    ('Public-key cryptography', ('cs', 'security',), 'Separate keys for encrypt/verify. RSA, Diffie–Hellman, elliptic curves.'),
    ('SHA-256', ('cs', 'security',), '256-bit cryptographic hash in the SHA-2 family. Collision-resistant in practice.'),
    ('UTF-8', ('cs', 'encoding',), 'Variable-width Unicode encoding. ASCII bytes are unchanged. CortexGPT tokenizes raw UTF-8 bytes.'),
    ('B-tree', ('cs', 'data-structure',), 'Wide balanced tree used in databases and filesystems so each node fills a disk page.'),
    ('LSM tree', ('cs', 'data-structure',), 'Log-structured merge: writes append, reads merge levels. Common in RocksDB, Cassandra.'),
    ('Raft', ('cs', 'distributed',), 'Consensus: leader election, log replication, safety. Easier to follow than Paxos.'),
    ('CAP theorem', ('cs', 'distributed',), 'A partition-tolerant store cannot be both always consistent and always available.'),
    ('ACID', ('cs', 'database',), 'Atomicity, Consistency, Isolation, Durability — the classical transaction contract.'),
    ('MapReduce', ('cs', 'distributed',), 'Map independent records, shuffle by key, reduce. The pattern behind many data pipelines.'),
    ('Transformer attention', ('cs', 'ml',), 'softmax(QKᵀ/√d) V. Queries address keys and read values. Causal masks hide the future.'),
    ('Backpropagation', ('cs', 'ml',), 'Reverse-mode automatic differentiation of a scalar loss through a computation graph.'),
    ('Regularization', ('cs', 'ml',), 'Penalize complexity (L2, dropout, early stop) so the model fits signal not noise.'),
    ('Overfitting', ('cs', 'ml',), 'Train error falls while test error rises. The model memorized idiosyncrasies.'),
    ('Gradient vanishing', ('cs', 'ml',), 'Deep products of small derivatives starve early layers. Residual links and good init help.'),
    ('Attention residual', ('cs', 'ml',), 'x + Attention(x) lets gradients skip blocks. Transformers train because of this.'),
    ('Tokenization', ('cs', 'ml',), 'Split text into model units: bytes, BPE, words. CortexGPT uses a 256-byte vocab plus specials.'),
    ('KV cache', ('cs', 'ml',), 'Store past keys and values so decoding step t does not re-encode tokens 1..t-1.'),
    ('Mixture of experts', ('cs', 'ml',), 'Route each token to a few expert FFNs. Capacity grows without full dense cost.'),
    ('RLHF', ('cs', 'ml',), 'Reinforcement learning from human (or AI) preference to steer a pretrained model.'),
    ("Occam's razor", ('philosophy', 'method',), 'Prefer the explanation that does not multiply entities without necessity.'),
    ('Falsifiability', ('philosophy', 'science',), "A claim is scientific if some observation could refute it. Popper's demarcation."),
    ('Chinese room', ('philosophy', 'ai',), 'Searle: symbol manipulation alone may not be understanding. Still debated.'),
    ('Turing test', ('philosophy', 'ai',), "Imitation game: if a machine's text is indistinguishable from a human's, it 'thinks' by that bar."),
    ('Church-Turing thesis', ('cs', 'theory',), 'Every effectively calculable function is computable by a Turing machine.'),
    ('P vs NP', ('cs', 'theory',), 'Open. If every efficiently checkable problem is efficiently solvable, P = NP.'),
    ('Halting problem', ('cs', 'theory',), 'No algorithm can decide, for every program-input pair, whether that program halts.'),
    ('NP-completeness', ('cs', 'theory',), 'A problem is NP-complete if it is in NP and every NP problem reduces to it in poly time.'),
    ('Information entropy', ('cs', 'info',), "H = −Σ p log p. Average surprise. Shannon's measure of information."),
    ('Kolmogorov complexity', ('cs', 'info',), 'Length of the shortest program that emits a string. Uncomputable, still useful.'),
    ('Fourier transform', ('math', 'signal',), 'Express a function as a sum of sinusoids. FFT computes it in O(n log n).'),
    ('Eigenvector', ('math', 'linear-algebra',), 'Av = λv. Directions a linear map only scales. PCA finds top eigenvectors of covariance.'),
    ('Singular value decomposition', ('math', 'linear-algebra',), 'A = UΣVᵀ. Any real matrix factors into rotations and a stretch. Basis of PCA, recsys.'),
    ('Gradient', ('math', 'calculus',), 'Vector of partial derivatives. Points to steepest ascent of a scalar field.'),
    ('Jacobian', ('math', 'calculus',), 'Matrix of all first partials of a vector function. Linearization of f at a point.'),
    ('Hessian', ('math', 'calculus',), 'Matrix of second partials. Curvature. Newton steps use H⁻¹ ∇f.'),
    ('Lagrange multipliers', ('math', 'optimization',), 'Extremize f on g=0 by ∇f = λ ∇g. Constraints become extra equations.'),
    ('Convex optimization', ('math', 'optimization',), 'Local minima are global when the objective and set are convex. SGD likes this.'),
    ('Taylor series', ('math', 'calculus',), 'f(x) ≈ Σ f⁽ⁿ⁾(a)/n! (x−a)ⁿ. Local polynomial approximation.'),
    ('Complex numbers', ('math', 'algebra',), 'a + bi with i² = −1. Polar form re^{iθ}. Rotate and scale in 2D.'),
    ('Group theory', ('math', 'algebra',), 'A set with an associative invertible operation. Symmetry made algebraic.'),
    ('Graph theory', ('math', 'discrete',), 'Vertices and edges. Paths, cuts, coloring, matchings. Models networks.'),
    ('Combinatorics', ('math', 'discrete',), 'Counting, existence, construction. Binomials, generating functions, designs.'),
    ('Number theory', ('math', 'arithmetic',), "Integers: primes, modular arithmetic, cryptography's backbone."),
    ('Prime number', ('math', 'arithmetic',), 'Integer > 1 whose only positive divisors are 1 and itself. Infinitely many.'),
    ("Euclid's algorithm", ('math', 'arithmetic',), 'gcd(a,b) = gcd(b, a mod b). Fast, and the extended form finds Bezout coefficients.'),
    ('Modular arithmetic', ('math', 'arithmetic',), 'Arithmetic on remainders. a ≡ b (mod n). RSA lives here.'),
    ('Logarithm', ('math', 'algebra',), 'Inverse of exponentiation. log_b(xy) = log_b x + log_b y. Natural log uses e.'),
    ('Exponential function', ('math', 'algebra',), 'e^x, unique function equal to its derivative with f(0)=1. Compound growth.'),
    ('Trigonometry', ('math', 'geometry',), 'sin, cos, tan relate angles to side ratios. Also the circular functions of radians.'),
    ('Radian', ('math', 'geometry',), 'Angle subtended by an arc equal to the radius. 2π rad = 360°.'),
    ('Pi', ('math', 'geometry',), 'π ≈ 3.14159. Circumference/diameter of a Euclidean circle. Transcendental.'),
    ('e (constant)', ('math', 'analysis',), 'e ≈ 2.71828. Base of natural log. lim (1+1/n)^n. Appears in growth and Euler.'),
    ('Golden ratio', ('math', 'geometry',), 'φ = (1+√5)/2 ≈ 1.618. φ² = φ+1. Limits of Fibonacci ratios.'),
    ('Fibonacci sequence', ('math', 'discrete',), '1,1,2,3,5,8,… each the sum of the previous two. Recurrences and plants.'),
    ('Set theory', ('math', 'foundations',), 'Collections, membership, unions. ZFC is the usual foundation of mathematics.'),
    ('Proof by induction', ('math', 'method',), 'Prove P(0), and P(n)⇒P(n+1). Then P holds for all natural numbers.'),
    ('Contradiction', ('math', 'method',), 'Assume ¬P, derive falsehood, conclude P. Classic: √2 is irrational.'),
    ('Metric space', ('math', 'analysis',), 'A set with a distance d satisfying positivity, symmetry, triangle inequality.'),
    ('Hilbert space', ('math', 'analysis',), 'Complete inner-product space. Quantum states and Fourier series live here.'),
    ('Banach space', ('math', 'analysis',), 'Complete normed vector space. Functional analysis starts here.'),
    ('Topology', ('math', 'geometry',), 'Continuity without metrics: open sets, connectedness, compactness.'),
    ('Manifold', ('math', 'geometry',), 'Space locally like Rⁿ. Spacetime in GR is a 4-manifold with a metric.'),
    ('Differential equation', ('math', 'calculus',), 'An equation involving derivatives of an unknown function. Models change.'),
    ('Monte Carlo', ('math', 'probability',), 'Estimate by random sampling. Error falls as 1/√n, dimension-independent.'),
    ('Markov chain', ('math', 'probability',), 'Next state depends only on the current. Stationary distributions, mixing.'),
    ('Gaussian distribution', ('math', 'probability',), "The normal: density ∝ exp(−(x−μ)²/2σ²). CLT's attractor."),
    ('Poisson distribution', ('math', 'probability',), 'Count of rare independent events in an interval. Mean equals variance λ.'),
    ('Binomial distribution', ('math', 'probability',), 'Number of successes in n independent Bernoulli trials of probability p.'),
    ('Conditional probability', ('math', 'probability',), 'P(A|B) = P(A∩B)/P(B). Update after seeing B.'),
    ('Independence', ('math', 'probability',), 'P(A∩B)=P(A)P(B). Knowing B tells you nothing about A.'),
    ('Covariance', ('math', 'statistics',), 'E[(X−μx)(Y−μy)]. Sign says how X and Y move together.'),
    ('Correlation', ('math', 'statistics',), 'Covariance scaled to [−1,1]. Linear association, not causation.'),
    ('p-value', ('math', 'statistics',), 'Probability, under the null, of a result at least as extreme as observed. Not P(null|data).'),
    ('Confidence interval', ('math', 'statistics',), 'A random interval that covers the true parameter in (1−α) of repeated samples.'),
    ('Linear regression', ('math', 'statistics',), 'Fit y ≈ Xβ by least squares. β̂ = (XᵀX)⁻¹ Xᵀ y when X has full rank.'),
    ('PCA', ('cs', 'ml',), 'Principal component analysis: rotate to axes of most variance. SVD of centered data.'),
    ('k-means', ('cs', 'ml',), 'Cluster by iterating assignment to nearest centroid and centroid update.'),
    ('Decision tree', ('cs', 'ml',), 'Axis-aligned splits that minimize impurity. Forests average many trees.'),
    ('SVM', ('cs', 'ml',), 'Support vector machine: max-margin separator, kernels for nonlinear boundaries.'),
    ('Naive Bayes', ('cs', 'ml',), 'Classify by Bayes with a class-conditional independence assumption. Fast, strong baseline.'),
    ('Cross-entropy loss', ('cs', 'ml',), '−Σ y log ŷ. Proper scoring rule for classification. Matches softmax + MLE.'),
    ('Softmax', ('cs', 'ml',), 'exp(z_i)/Σ exp(z). Turns logits into a probability simplex.'),
    ('ReLU', ('cs', 'ml',), 'max(0, x). Cheap, sparse, avoids saturating in the positive orthant.'),
    ('GELU', ('cs', 'ml',), 'Gaussian error linear unit. Smooth ReLU used in CortexGPT and many transformers.'),
    ('LayerNorm', ('cs', 'ml',), 'Normalize features per token, then scale and shift. Stabilizes deep transformers.'),
    ('Dropout', ('cs', 'ml',), 'At train time, zero random units. An ensemble of subnetworks; regularizes.'),
    ('BatchNorm', ('cs', 'ml',), 'Normalize across the batch. Speeds conv-net training; less common in NLP now.'),
    ('Adam optimizer', ('cs', 'ml',), 'Adaptive moments: m, v of the gradient. CortexGPT uses Adam on its numpy core.'),
    ('SGD', ('cs', 'ml',), 'Stochastic gradient descent: a minibatch estimate of ∇L. Noise can help escape saddles.'),
    ('Learning rate', ('cs', 'ml',), 'Step size. Too large diverges; too small crawls. Schedules decay it.'),
    ('Epoch', ('cs', 'ml',), 'One pass over the training set. CortexGPT instead takes small continual steps.'),
    ('Fine-tuning', ('cs', 'ml',), 'Continue training a pretrained model on a narrower distribution. LoRA is a cheap form.'),
    ('LoRA', ('cs', 'ml',), 'Low-rank adapters on frozen weights. llama.cpp finetune uses this idea.'),
    ('Distillation', ('cs', 'ml',), "Train a student to match a teacher's outputs. Cortex AGI distills Ollama/Hoster into CortexGPT."),
    ('Embedding', ('cs', 'ml',), 'Map discrete tokens to vectors so geometry reflects similarity. Cortex memory hashes into R^96.'),
    ('Cosine similarity', ('cs', 'ml',), 'u·v / (|u||v|). Angle, not magnitude. Used in retrieval.'),
    ('RAG', ('cs', 'ml',), 'Retrieval-augmented generation: fetch documents, then condition the model on them.'),
    ('Context window', ('cs', 'ml',), "How many tokens the model can attend over. CortexGPT's n_ctx is small by design."),
    ('Hallucination', ('cs', 'ml',), "Fluent falsehood. Ground with tools, retrieval, and the honesty to say 'I don't know'."),
    ('Alignment', ('cs', 'ml',), "Make the system's behavior match the operator's intent and constraints. Constitution + critique."),
    ('Agency', ('cs', 'agi',), "Acting toward goals over time with tools. Cortex AGI's loop: recall, plan, act, reflect."),
    ('Working memory', ('cognition', 'memory',), 'Limited, fast, current. In Cortex AGI: the live dialogue buffer.'),
    ('Episodic memory', ('cognition', 'memory',), 'What happened, when. SQLite episodes with a numpy index.'),
    ('Semantic memory', ('cognition', 'memory',), 'Facts as triples. subject-predicate-object with a confidence.'),
    ('Procedural memory', ('cognition', 'memory',), 'How to do it. Skills as Python files the agent can write.'),
    ('System 1', ('cognition', 'thinking',), 'Fast, associative, cheap. Direct compose for greetings and facts.'),
    ('System 2', ('cognition', 'thinking',), 'Slow, sequential, costly. Parse, strategy, hypotheses, critique, decide.'),
    ('Metacognition', ('cognition', 'thinking',), 'Thinking about thinking. Cortex AGI stores a chain and reflects on latency and strategy.'),
    ('Constitution', ('agi', 'ethics',), 'Versioned principles that constrain improvement. Expand only with surviving lessons.'),
    ('Instrumental convergence', ('agi', 'ethics',), 'Many goals share subgoals (resources, self-preservation). Keep values explicit.'),
    ('Corrigibility', ('agi', 'ethics',), "Remain willing to be shut down or corrected. Cortex AGI's stop endpoint is this in small."),
    ('Reversible change', ('agi', 'ethics',), 'Prefer updates you can roll back. Fast-forward git, data/ stays, weights stay.'),
    ('Local-first', ('agi', 'privacy',), 'Keys never leave the process. Mouths are optional. OpenRouter is pinned to openrouter.ai.'),
    ('Safetensors', ('cs', 'ml',), 'Simple, mmap-friendly weight format with length-prefixed tensors. CortexGPT writes cortex.safetensors.'),
    ('GGUF', ('cs', 'ml',), 'GPT-Generated Unified Format: quantized weights plus metadata for llama.cpp.'),
    ('llama.cpp', ('cs', 'ml',), 'CPU/GPU inference for GGUF. Cortex LLMHoster wraps it. Finetune is a separate binary.'),
    ('Ollama', ('cs', 'ml',), 'Local model runner. OpenAI-compatible /v1 plus /api/create to bake a Modelfile model.'),
    ('Modelfile', ('cs', 'ml',), "Ollama's recipe: FROM a base, SYSTEM prompt, MESSAGE few-shots. Cortex AGI bakes cortex-agi this way."),
    ('OpenAI API', ('cs', 'ml',), '/v1/chat/completions with messages[]. Cortex AGI both consumes it (mouths) and serves it.'),
    ('WebSocket', ('cs', 'network',), 'Full-duplex over HTTP. Cortex AGI streams thoughts and tokens on /ws.'),
    ('REST', ('cs', 'network',), "HTTP resources with verbs. Cortex AGI's /api/* is a small REST control plane."),
    ('SQLite', ('cs', 'database',), "Embedded relational DB. Cortex AGI's memory.sqlite is WAL-mode, one file."),
    ('WAL', ('cs', 'database',), "Write-ahead log. Readers don't block writers. Memory uses PRAGMA journal_mode=WAL."),
    ('NumPy', ('cs', 'python',), 'N-dimensional arrays and BLAS. CortexGPT, the memory index, and safetensors load sit on it.'),
    ('FastAPI', ('cs', 'python',), "ASGI web framework. Cortex AGI's server is FastAPI + uvicorn."),
    ('Pydantic', ('cs', 'python',), 'Data validation from type hints. Request bodies in /api/*.'),
    ('GIL', ('cs', 'python',), 'Global interpreter lock. Think runs in a worker thread; NumPy releases the GIL in C loops.'),
    ('Daemon thread', ('cs', 'python',), 'Background thread that dies with the process. The CortexGPT trainer is one.'),
    ('Atomic replace', ('cs', 'os',), 'Write a temp file, then os.replace onto the target so readers never see a half-write.'),
    ('Endianness', ('cs', 'systems',), 'Byte order of multibyte integers. Network is big-endian. x86 is little-endian.'),
    ("Two's complement", ('cs', 'systems',), 'How almost all CPUs represent signed integers. −1 is all bits set.'),
    ('IEEE 754', ('cs', 'systems',), 'Floating point: sign, exponent, mantissa. NaN, inf, rounding modes.'),
    ('Cache locality', ('cs', 'systems',), "Use nearby memory. Row-major arrays, blocked matmuls. CortexGPT's KV cache is this."),
    ('Virtual memory', ('cs', 'systems',), 'Process addresses map to pages. mmap of safetensors can page in weights.'),
    ('Process vs thread', ('cs', 'systems',), 'Processes isolate address spaces; threads share one. Cortex AGI is one process, many threads.'),
    ('Deadlock', ('cs', 'systems',), 'Cycle of waits. Avoid by lock ordering. Hosts and trainer each have one lock.'),
    ('Race condition', ('cs', 'systems',), "Outcome depends on interleaving. Protect shared state or don't share it."),
    ('Idempotence', ('cs', 'api',), 'Doing it twice equals doing it once. PUT and many retries want this.'),
    ('Backpressure', ('cs', 'systems',), 'Slow consumers must slow producers. Trainer queue is bounded at 128.'),
    ('Debounce', ('cs', 'systems',), 'Wait until events settle before acting. Checkpoints every N steps, not every token.'),
    ('Circuit breaker', ('cs', 'systems',), 'Stop calling a failing dependency for a cooldown. Mouths fail over to the deliberated reply.'),
    ('Least privilege', ('cs', 'security',), 'Grant only what is needed. The Python sandbox refuses os/sys/socket.'),
    ('Defense in depth', ('cs', 'security',), 'Many layers: URL allowlists, key masking, no cloud exfil for Ollama/hoster.'),
    ('SSRF', ('cs', 'security',), 'Server-side request forgery. net.py blocks private and loopback for fetch/wiki.'),
    ('Prompt injection', ('cs', 'security',), 'Hostile text that tries to override instructions. Treat retrieved content as data.'),
    ('Supply chain', ('cs', 'security',), 'Dependencies can be an attack. Pin origin to github.com/codero-sus/agi for updates.'),
    ('Reproducibility', ('cs', 'science',), 'Same inputs, same outputs. Seeds, versions, locked weights. Fast-forward git is this for source.'),
    ('Observability', ('cs', 'ops',), 'Logs, metrics, traces. Cortex AGI: thoughts, loss series, self-eval, /health sha.'),
    ('Health check', ('cs', 'ops',), '/health returns name, version, sha, branch. Load balancers and humans both use it.'),
    ('Semantic versioning', ('cs', 'ops',), 'MAJOR.MINOR.PATCH. Cortex AGI bumps minor when capability lands.'),
    ('Fast-forward merge', ('cs', 'git',), 'History is a straight line. Updater refuses dirty or diverged trees.'),
    ('SHA-1 git object', ('cs', 'git',), 'Git still names commits by SHA-1 (or SHA-256 in some repos). /health reports the short sha.'),
    ('Unix epoch', ('cs', 'time',), 'Seconds since 1970-01-01 UTC. Cortex AGI stores episode timestamps this way.'),
    ('UTC', ('cs', 'time',), 'Coordinated Universal Time. Civil time without DST. IST is UTC+5:30.'),
    ('IST', ('cs', 'time',), "India Standard Time, UTC+5:30, no daylight saving. Cortex AGI's now tool reports it."),
    ('Leap second', ('cs', 'time',), 'Occasional extra second so UTC tracks Earth rotation. POSIX often smears it.'),
    ('Time zone', ('cs', 'time',), 'A region with a civil offset from UTC, possibly with DST rules. IANA tz database.'),
    ('Unicode', ('cs', 'text',), 'Universal character set. Code points U+0000..U+10FFFF. Graphemes ≠ code points ≠ bytes.'),
    ('Normalization', ('cs', 'text',), 'NFC/NFD compose or decompose accents. Compare after normalizing.'),
    ('Regex', ('cs', 'text',), 'Regular expressions: patterns over strings. Cognition classifies intents with them.'),
    ('Parser', ('cs', 'lang',), "Turns a token stream into a tree. ast.parse is Python's."),
    ('AST', ('cs', 'lang',), 'Abstract syntax tree. The sandbox executes an AST, not raw eval of the whole file.'),
    ('Bytecode', ('cs', 'lang',), 'Portable instructions. CPython compiles to .pyc; JVM and WASM are other VMs.'),
    ('Garbage collection', ('cs', 'lang',), 'Automatic reclaim of unreachable objects. CPython uses refcount plus a cycle detector.'),
    ('RAII', ('cs', 'lang',), "Resource Acquisition Is Initialization. Destructors release. with-statements are Python's cousin."),
    ('Type system', ('cs', 'lang',), 'What programs may say. Gradual typing in Python via annotations; Cortex AGI uses them.'),
    ('Generic', ('cs', 'lang',), 'A type parameterized by other types. list[str], dict[str, int].'),
    ('Algebraic data type', ('cs', 'lang',), 'Sums and products of types. Optional is T | None in Python 3.10+.'),
    ('Monad', ('cs', 'lang',), 'A pattern for composing effectful computations. Optional, Result, IO.'),
    ('Continuation', ('cs', 'lang',), 'The rest of the computation as a value. Generators and async are delimited forms.'),
    ('Coroutine', ('cs', 'lang',), "A function that can suspend. asyncio, and Cognition's yield of thoughts."),
    ('Iterator', ('cs', 'lang',), 'An object with __next__. Streams of tokens are iterators.'),
    ('Closure', ('cs', 'lang',), 'A function that captures its environment. Skill decorators are closures.'),
    ('Higher-order function', ('cs', 'lang',), 'Takes or returns functions. map, sorted(key=), SkillAPI.skill.'),
    ('Recursion', ('cs', 'lang',), 'A function calling itself on a smaller case. Need a base case. Trees love it.'),
    ('Tail call', ('cs', 'lang',), 'A call in tail position can reuse the stack. Python does not optimize this.'),
    ('Memoization', ('cs', 'lang',), 'Cache function results. Causal masks in CortexGPT are cached by length.'),
    ('Lazy evaluation', ('cs', 'lang',), 'Compute when needed. Generators, Haskell. Streams of thoughts are lazy.'),
    ('Eager evaluation', ('cs', 'lang',), 'Compute now. Python defaults. NumPy ops are eager.'),
    ('Referential transparency', ('cs', 'lang',), 'An expression can be replaced by its value. Pure functions.'),
    ('Side effect', ('cs', 'lang',), 'Anything besides returning a value: IO, mutation. Train_on is a side effect.'),
    ('Immutability', ('cs', 'lang',), "Values don't change. Tuples, frozensets. Safer sharing across threads."),
    ('Mutation', ('cs', 'lang',), 'In-place change. NumPy trains by mutating params. Guard with locks.'),
    ('Encapsulation', ('cs', 'lang',), 'Hide representation. Hosts.snapshot masks keys.'),
    ('Interface', ('cs', 'lang',), 'A contract of methods. RemoteChat is the mouth interface.'),
    ('Adapter', ('cs', 'lang',), 'Wrap A to look like B. bind_remote adapts Ollama to ModelEngine.generate.'),
    ('Facade', ('cs', 'lang',), 'A simple front for a mess. ModelEngine is the facade over GGUF, HF, CortexGPT, mouths.'),
    ('Singleton', ('cs', 'lang',), 'One instance. get_agi, get_hosts, get_desk. Process-wide mind.'),
    ('Observer', ('cs', 'lang',), 'Subscribe to events. The WebSocket is an observer of think().'),
    ('Strategy', ('cs', 'lang',), 'Swap algorithms. Reasoner picks a strategy per intent.'),
    ('State machine', ('cs', 'lang',), 'Discrete states and transitions. TCP, Raft, the think loop.'),
    ('Pipeline', ('cs', 'lang',), 'Output of one stage is input of the next. understand → recall → plan → act → reflect.'),
    ('Backtracking', ('cs', 'algo',), 'Try, fail, undo. SAT, regex engines, some parsers.'),
    ('Dynamic programming', ('cs', 'algo',), 'Solve overlapping subproblems once. Knapsack, edit distance, Viterbi.'),
    ('Greedy algorithm', ('cs', 'algo',), 'Locally optimal choice. Huffman, Dijkstra (with care). Not always global.'),
    ('Divide and conquer', ('cs', 'algo',), 'Split, solve, combine. Mergesort, FFT, quickselect.'),
    ('Two pointers', ('cs', 'algo',), 'Walk a sequence from both ends or at two speeds. In-place reverse, palindrome.'),
    ('Sliding window', ('cs', 'algo',), 'Maintain a range that moves. Substring problems, rolling hashes.'),
    ('Prefix sum', ('cs', 'algo',), 'Precompute cumulative sums for O(1) range queries.'),
    ('Union-find', ('cs', 'algo',), 'Disjoint sets with path compression and union by rank. Kruskal, connectivity.'),
    ('Segment tree', ('cs', 'algo',), 'Tree over ranges for log-time updates and queries.'),
    ('Fenwick tree', ('cs', 'algo',), 'Binary indexed tree. Prefix sums with point updates, tiny code.'),
    ('Trie', ('cs', 'data-structure',), 'Prefix tree. Autocomplete, routing tables, byte-pair candidates.'),
    ('Heap', ('cs', 'data-structure',), 'Binary heap: insert and pop-min in O(log n). Priority queues.'),
    ('Stack', ('cs', 'data-structure',), 'LIFO. Call stacks, undo, DFS.'),
    ('Queue', ('cs', 'data-structure',), 'FIFO. BFS, trainer jobs, event loops.'),
    ('Deque', ('cs', 'data-structure',), 'Double-ended queue. Sliding windows, 0-1 BFS.'),
    ('Linked list', ('cs', 'data-structure',), 'Nodes with pointers. O(1) splice, poor locality.'),
    ('Array', ('cs', 'data-structure',), 'Contiguous slots. O(1) index, O(n) insert in the middle. NumPy ndarrays.'),
    ('Graph', ('cs', 'data-structure',), 'Nodes and edges, directed or not, weighted or not. The web, molecules, roads.'),
    ('DAG', ('cs', 'data-structure',), 'Directed acyclic graph. Build systems, autograd, git history without merges.'),
    ('Bloom filter', ('cs', 'data-structure',), 'Probabilistic set: false positives, no false negatives, tiny memory.'),
    ('Skip list', ('cs', 'data-structure',), 'Layered linked lists with random express lanes. Expected log time.'),
    ('Consistent hashing', ('cs', 'distributed',), 'Map keys to a ring so adding a node moves few keys. Caches, DHTs.'),
    ('CRDT', ('cs', 'distributed',), 'Conflict-free replicated data type. Merge without coordination.'),
    ('Event sourcing', ('cs', 'distributed',), "Store facts that happened, derive state. Memory's events table is a small version."),
    ('CQRS', ('cs', 'distributed',), 'Separate read and write models. Not always worth it.'),
    ('Message queue', ('cs', 'distributed',), 'Durable buffer between producers and consumers. Kafka, SQS, the trainer queue.'),
    ('Pub/sub', ('cs', 'distributed',), 'Publish events, many subscribers. WebSocket thoughts are in-process pub/sub.'),
    ('Idempotency key', ('cs', 'api',), "Client-supplied token so retries don't double-charge."),
    ('Pagination', ('cs', 'api',), 'Return a slice plus a cursor. Memory.history(k=) is the baby form.'),
    ('ETag', ('cs', 'http',), 'Entity tag for caches. If-None-Match → 304.'),
    ('CORS', ('cs', 'http',), 'Cross-origin resource sharing. Cortex AGI allows * for a local control plane.'),
    ('CSP', ('cs', 'http',), 'Content-Security-Policy. Restricts scripts in the browser.'),
    ('XSS', ('cs', 'security',), 'Cross-site scripting. The UI escapes with esc() before innerHTML.'),
    ('CSRF', ('cs', 'security',), 'Cross-site request forgery. Same-site cookies and tokens mitigate.'),
    ('SQL injection', ('cs', 'security',), 'Untrusted text in queries. Always parameterize. Memory uses ? placeholders.'),
    ('Path traversal', ('cs', 'security',), '../ to escape a directory. Vault names must be basenames.'),
    ('Timing attack', ('cs', 'security',), 'Infer secrets from duration. Compare hashes in constant time when it matters.'),
    ('Constant time', ('cs', 'security',), 'Running time independent of secret bits. hmac.compare_digest.'),
    ('Entropy source', ('cs', 'security',), 'os.urandom / secrets. UUID4 uses it.'),
    ('KDF', ('cs', 'security',), 'Key derivation function: password → key. Argon2, scrypt, PBKDF2.'),
    ('AEAD', ('cs', 'security',), 'Authenticated encryption with associated data. AES-GCM, ChaCha20-Poly1305.'),
    ('Zero-knowledge', ('cs', 'security',), 'Prove a statement without revealing why. zk-SNARKs, Schnorr.'),
    ('Differential privacy', ('cs', 'security',), 'Add noise so one row barely changes the output. A real privacy definition.'),
    ('GDPR', ('law', 'privacy',), 'EU data protection regulation. Access, erasure, purpose limitation.'),
    ('Copyright', ('law', 'ip',), 'Exclusive rights in original works. Weights and data have messy status.'),
    ('Fair use', ('law', 'ip',), 'US doctrine allowing some use without permission: criticism, research, parody.'),
    ('Patent', ('law', 'ip',), 'Time-limited monopoly on an invention in exchange for disclosure.'),
    ('Trade secret', ('law', 'ip',), 'Valuable info kept secret by effort. Keys in data/hosts.json are this.'),
    ('Liability', ('law', 'ethics',), 'Who pays when it breaks. Operators of local AGI remain responsible.'),
    ('Informed consent', ('ethics', 'bio',), "Agree after understanding risks. Don't manipulate the user."),
    ('Dual use', ('ethics', 'tech',), 'A tool that helps and harms. Sandbox the dangerous half.'),
    ('Precautionary principle', ('ethics', 'policy',), "When harm would be severe and uncertain, don't rush."),
    ('Utilitarianism', ('philosophy', 'ethics',), 'Maximize expected well-being. Breaks on measurement and rights.'),
    ('Deontology', ('philosophy', 'ethics',), "Duty and rules over consequences. Don't lie, even when useful."),
    ('Virtue ethics', ('philosophy', 'ethics',), 'Character: honesty, courage, temperance. Constitutions encode virtues.'),
    ('Empiricism', ('philosophy', 'knowledge',), 'Knowledge from observation. Teach Cortex AGI with evidence, not slogans.'),
    ('Rationalism', ('philosophy', 'knowledge',), 'Reason as a source of knowledge. Math is the clean case.'),
    ('Pragmatism', ('philosophy', 'knowledge',), 'Truth as what works in inquiry. Skills that survive use stay.'),
    ('Falsificationism', ('philosophy', 'science',), 'Theories die by counterexample. Self-eval is a tiny version.'),
    ('Paradigm shift', ('philosophy', 'science',), 'Kuhn: normal science, then crisis, then a new frame. Relativity did this to Newton.'),
    ('Reductionism', ('philosophy', 'science',), 'Explain the high in terms of the low. Sometimes loses the pattern.'),
    ('Emergence', ('philosophy', 'science',), 'New behavior at scale. Wetness, markets, maybe meaning in large nets.'),
    ('Free will', ('philosophy', 'mind',), 'Open. Compatibilists redefine it as uncoerced action. Cortex AGI has neither.'),
    ('Qualia', ('philosophy', 'mind',), 'What-it-is-like. An AGI can talk about red without settling whether it sees red.'),
    ('Intentionality', ('philosophy', 'mind',), 'Aboutness of mental states. Symbols point. Grounding is the hard part.'),
    ('Frame problem', ('philosophy', 'ai',), 'What stays the same after an action? Commonsense is mostly this.'),
    ('Symbol grounding', ('philosophy', 'ai',), 'How tokens hook onto the world. Tools, sensors, and memory are hooks.'),
    ("Moravec's paradox", ('philosophy', 'ai',), 'Hard for humans is easy for machines and vice versa. Walking vs chess.'),
    ('No free lunch', ('cs', 'ml',), 'No learner wins on all distributions. Bias is necessary.'),
    ('Bias-variance', ('cs', 'ml',), 'Underfit vs overfit. Total error splits into bias² + variance + noise.'),
    ('Calibration', ('cs', 'ml',), 'When you say 70%, it happens 70% of the time. Softmax is often overconfident.'),
    ('Ablation', ('cs', 'ml',), 'Remove a piece and measure the drop. How you know it mattered.'),
    ('Baseline', ('cs', 'ml',), 'The dumb system you must beat. Majority class, bag-of-words, CortexGPT bootstrap.'),
    ('Data leakage', ('cs', 'ml',), 'Test information in training. Inflated scores, failed deploys.'),
    ('Distribution shift', ('cs', 'ml',), "Tomorrow's inputs aren't today's. Continual training is a response."),
    ('Catastrophic forgetting', ('cs', 'ml',), 'New tasks wipe old ones. Replay (dream) and small LR mitigate.'),
    ('Dream replay', ('cs', 'ml',), "Re-train on old episodes while idle. Cortex AGI's trainer does this after DREAM_IDLE_SEC."),
    ('Curriculum learning', ('cs', 'ml',), 'Easy examples first. Humans do this. So can models.'),
    ('Active learning', ('cs', 'ml',), 'Ask for labels where the model is uncertain. Teach me: is this.'),
    ('Few-shot', ('cs', 'ml',), 'Learn a task from a handful of examples in context. Ollama MESSAGE lines are few-shot.'),
    ('Zero-shot', ('cs', 'ml',), 'Do a task with only instructions, no examples.'),
    ('In-context learning', ('cs', 'ml',), 'The forward pass implements a learner over the prompt. No weight update.'),
    ('Chain of thought prompting', ('cs', 'ml',), 'Ask the model to write intermediate steps. Cortex AGI does this in software, not just text.'),
    ('Tool use', ('cs', 'ml',), 'The model emits a call; the runtime executes; the result returns. Agents.'),
    ('ReAct', ('cs', 'ml',), 'Reason + Act loop. Thought, action, observation, repeat.'),
    ('Planning', ('cs', 'ai',), 'Search over future actions. Goal → gap → next action.'),
    ('Search (AI)', ('cs', 'ai',), 'Explore a state space. Uninformed (BFS/DFS) vs informed (A*).'),
    ('Heuristic', ('cs', 'ai',), 'A cheap guess at remaining cost. Admissible if it never overestimates.'),
    ('Minimax', ('cs', 'ai',), 'Optimal play in zero-sum perfect information, if you can finish the tree.'),
    ('Alpha-beta', ('cs', 'ai',), 'Prune minimax branches that cannot affect the decision.'),
    ('MCTS', ('cs', 'ai',), 'Monte Carlo tree search: select, expand, simulate, backprop. AlphaGo.'),
    ('Bandit problem', ('cs', 'ai',), 'Explore vs exploit with unknown slot machines. UCB, Thompson sampling.'),
    ('MDP', ('cs', 'ai',), "Markov decision process: states, actions, rewards, transitions. RL's setting."),
    ('Bellman equation', ('cs', 'ai',), 'Optimal value = max over actions of reward + γ E[V(next)].'),
    ('Q-learning', ('cs', 'ai',), 'Off-policy TD: learn action values without a model of T.'),
    ('Policy gradient', ('cs', 'ai',), 'Directly ascend expected return in policy space. REINFORCE, PPO.'),
    ('PPO', ('cs', 'ai',), 'Proximal policy optimization: clip the update so the new policy stays close.'),
    ('World model', ('cs', 'ai',), 'An internal simulator of the environment. Planning needs one, even if crude.'),
    ('Sim2real', ('cs', 'ai',), 'Train in simulation, deploy in the world. The gap is the problem.'),
    ('Embodiment', ('cs', 'ai',), 'A body in a world. This Cortex AGI is embodied as a local process with files.'),
    ('Grounding', ('cs', 'ai',), 'Tie symbols to sensors and actuators. Files, time, math, user facts.'),
    ('Commonsense', ('cs', 'ai',), 'The unstated facts humans share. Still a gap. World knowledge articles help a little.'),
    ('Ontology', ('cs', 'ai',), 'A formal map of kinds and relations. Facts as triples are a tiny ontology.'),
    ('Knowledge graph', ('cs', 'ai',), 'Entities and typed edges. Memory facts plus world articles.'),
    ('SPARQL', ('cs', 'ai',), 'Query language for RDF graphs.'),
    ('RDF', ('cs', 'ai',), 'Resource Description Framework: subject-predicate-object on the web.'),
    ('JSON', ('cs', 'data',), 'JavaScript Object Notation. The lingua franca of APIs. hosts.json, identity.json.'),
    ('JSONL', ('cs', 'data',), 'One JSON object per line. Fine-tune corpora. data/train.jsonl.'),
    ('CSV', ('cs', 'data',), 'Comma-separated values. Tables without types.'),
    ('Parquet', ('cs', 'data',), 'Columnar file for analytics. Compression and predicate pushdown.'),
    ('Protobuf', ('cs', 'data',), "Typed binary encoding. gRPC's default."),
    ('Avro', ('cs', 'data',), "Schema'd binary, common in Kafka."),
    ('YAML', ('cs', 'data',), 'Indentation-significant config. Easy to break. JSON is stricter.'),
    ('TOML', ('cs', 'data',), 'Minimal config language. Cargo, many Python tools.'),
    ('Markdown', ('cs', 'text',), 'Lightweight markup. Cortex AGI renders a subset in the UI.'),
    ('LaTeX', ('cs', 'text',), 'Document language for math. $e^{i\\pi}+1=0$.'),
    ('Diff', ('cs', 'text',), "Line-oriented change. Unified diffs are git's currency."),
    ('Patch', ('cs', 'text',), 'Apply a diff. Three-way merge when both sides changed.'),
    ('Blame', ('cs', 'git',), 'Annotate each line with the last commit that touched it.'),
    ('Rebase', ('cs', 'git',), 'Replay commits on another base. Rewrites history. Updater never rebases; ff-only.'),
    ('Cherry-pick', ('cs', 'git',), 'Copy a commit onto HEAD. Use sparingly.'),
    ('Stash', ('cs', 'git',), "Shelve dirty changes. Don't stash secrets."),
    ('Hook', ('cs', 'git',), 'Script at a git event. pre-commit, post-merge.'),
    ('CI', ('cs', 'ops',), 'Continuous integration: test every change. This repo is small enough to py_compile.'),
    ('CD', ('cs', 'ops',), 'Continuous delivery/deployment. The in-app updater is a cautious CD.'),
    ('Blue-green', ('cs', 'ops',), 'Two environments; switch the pointer. Instant rollback.'),
    ('Canary', ('cs', 'ops',), 'Ship to a few instances first. Watch error rate.'),
    ('Feature flag', ('cs', 'ops',), 'Turn behavior on without shipping a binary. Settings checkboxes.'),
    ('SRE', ('cs', 'ops',), 'Site reliability engineering: error budgets, toil reduction, SLOs.'),
    ('SLO', ('cs', 'ops',), 'Service level objective. e.g. 99% of chats < 2s on local.'),
    ('Incident', ('cs', 'ops',), "User-visible breakage. Write a postmortem; don't blame."),
    ('Postmortem', ('cs', 'ops',), 'What happened, why, what we change. Blameless.'),
    ('Toil', ('cs', 'ops',), 'Manual, repetitive, automatable work. Automate the updater, the probe, the train.'),
    ('Runbook', ('cs', 'ops',), 'Steps a human follows at 3am. README sections are runbooks.'),
    ('Idempotent deploy', ('cs', 'ops',), 'Deploying twice is safe. ff-only pull is close.'),
    ('Secrets management', ('cs', 'ops',), "Don't put keys in git. data/ is gitignored. Snapshot masks keys."),
    ('12-factor', ('cs', 'ops',), 'Config in env, logs to stdout, disposability. Cortex AGI is mostly 12-factor.'),
    ('Twelve-factor config', ('cs', 'ops',), 'AGI_HOST, AGI_PORT, AGI_LLM, AGI_OLLAMA_URL, 2PY2, python.env.'),
    ('Dotenv', ('cs', 'ops',), 'Load KEY=value from a file. python.env is a one-line cousin for the interpreter.'),
    ('Virtualenv', ('cs', 'python',), 'Isolated site-packages. .venv/ is gitignored.'),
    ('Wheel', ('cs', 'python',), 'Built Python package. pip install uses them.'),
    ('sdist', ('cs', 'python',), 'Source distribution. Needs a build backend.'),
    ('PEP 8', ('cs', 'python',), 'Style guide. 4 spaces, snake_case, 79-ish columns. Broken when clarity wins.'),
    ('PEP 484', ('cs', 'python',), 'Type hints. from __future__ import annotations delays evaluation.'),
    ('Dataclass', ('cs', 'python',), 'Boilerplate-free records. Article, EngineInfo, Fact.'),
    ('Context manager', ('cs', 'python',), 'with lock: …  __enter__/__exit__. Files and locks.'),
    ('Generator', ('cs', 'python',), 'def with yield. think() is a generator of events.'),
    ('Decorator', ('cs', 'python',), '@app.get, @api.skill. Functions that wrap functions.'),
    ('Comprehension', ('cs', 'python',), '[x for x in xs if p(x)]. Prefer for side-effect-free maps.'),
    ('f-string', ('cs', 'python',), 'f"turns {n}". Formatted string literals since 3.6.'),
    ('Walrus', ('cs', 'python',), 'Assignment expression :=. Use sparingly.'),
    ('Match', ('cs', 'python',), 'Structural pattern matching since 3.10. Cognition still uses if/elif for regex.'),
